package com.tiny.browser;import android.os.*;import android.webkit.*;import android.widget.*;public class MainActivity extends android.app.Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText u=new EditText(this);WebView w=new WebView(this);w.setWebViewClient(new WebViewClient());l.addView(u,-1,-2);l.addView(w,-1,-1);setContentView(l);w.loadUrl("https://google.com");u.setOnEditorActionListener((v,a,e)->{String s=u.getText().toString();w.loadUrl(s.contains(" ")?"https://google.com/search?q="+android.net.Uri.encode(s):"https://"+s);return true;});}}
